/**
 * Errors surfaced to Swift/Kotlin.
 *
 * This must not use `flat_error`: foreign `FfiCursorStore` implementations
 * return `FfiError`, and UniFFI cannot lift flat errors back into Rust
 * (`rustPanic("Can't lift flat errors")`). Keeping the message payloads
 * makes store failures round-trip instead of panicking.
 */
sealed class FfiException: kotlin.Exception() {

    class Network(

        val v1: kotlin.String
        ) : FfiException() {
        override val message
            get() = "v1=${ v1 }"
    }

    class NotConnected(
        ) : FfiException() {
        override val message
            get() = ""
    }

    class Timeout(
        ) : FfiException() {
        override val message
            get() = ""
    }

    class Cancelled(
        ) : FfiException() {
        override val message
            get() = ""
    }

    class Realtime(

        val v1: kotlin.String
        ) : FfiException() {
        override val message
            get() = "v1=${ v1 }"
    }

    class Codec(

        val v1: kotlin.String
        ) : FfiException() {
        override val message
            get() = "v1=${ v1 }"
    }

    class Storage(

        val v1: kotlin.String
        ) : FfiException() {
        override val message
            get() = "v1=${ v1 }"
    }

    class ReconnectExhausted(
        ) : FfiException() {
        override val message
            get() = ""
    }

    class Internal(

        val v1: kotlin.String
        ) : FfiException() {
        override val message
            get() = "v1=${ v1 }"
    }





    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): FfiException = FfiConverterTypeFfiError.lift(error_buf)
    }


}

/**
 * @suppress
 */
public object FfiConverterTypeFfiError : FfiConverterRustBuffer<FfiException> {
    override fun read(buf: ByteBuffer): FfiException {


        return when(buf.getInt()) {
            1 -> FfiException.Network(
                FfiConverterString.read(buf),
                )
            2 -> FfiException.NotConnected()
            3 -> FfiException.Timeout()
            4 -> FfiException.Cancelled()
            5 -> FfiException.Realtime(
                FfiConverterString.read(buf),
                )
            6 -> FfiException.Codec(
                FfiConverterString.read(buf),
                )
            7 -> FfiException.Storage(
                FfiConverterString.read(buf),
                )
            8 -> FfiException.ReconnectExhausted()
            9 -> FfiException.Internal(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiException): ULong {
        return when(value) {
            is FfiException.Network -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is FfiException.NotConnected -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.Timeout -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.Cancelled -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.Realtime -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is FfiException.Codec -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is FfiException.Storage -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is FfiException.ReconnectExhausted -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.Internal -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: FfiException, buf: ByteBuffer) {
        when(value) {
            is FfiException.Network -> {
                buf.putInt(1)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is FfiException.NotConnected -> {
                buf.putInt(2)
                Unit
            }
            is FfiException.Timeout -> {
                buf.putInt(3)
                Unit
            }
            is FfiException.Cancelled -> {
                buf.putInt(4)
                Unit
            }
            is FfiException.Realtime -> {
                buf.putInt(5)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is FfiException.Codec -> {
                buf.putInt(6)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is FfiException.Storage -> {
                buf.putInt(7)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is FfiException.ReconnectExhausted -> {
                buf.putInt(8)
                Unit
            }
            is FfiException.Internal -> {
                buf.putInt(9)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



